// stage 1: script detection (fast, deterministic)
const scripts = scriptDetector.detect(text);
if (scripts.length === 1) return scriptToLanguage(scripts[0]); // Hangul→Korean, done
// stage 2: frequency disambiguation only for multi-candidate scripts
return frequencyDetector.detect(text, scripts);

cases.bad:
// no fallback — returns null/unknown for languages without profiles
const lang = frequencyDetector.detect(text);
return lang ?? 'unknown';

